UPDATE spot SET overview = '가회동성당은 서울 종로구 북촌 한옥마을 언덕에 자리 잡은 성당으로 한국 천주교회의 상징적인 역사와 한옥의 고즈넉한 미학이 아우러진 아름다운 장소이다. 성당 건물은 한옥과 현대 건축 양식이 조화를 이루어 독특한 분위기를 연출하며, 북촌 특유의 고풍스러운 골목길과 이어져 많은 관광객과 출사 객들이 찾는 명소이다. 내부 성전은 정갈하고 차분한 분위기로 마음의 평화를 제공하며, 사계절 전경이 뛰어나 사진 촬영지로도 유명하다.' WHERE id = 1;
UPDATE spot SET overview = '갈산공원은 서울 양천구 신정동에 위치한 친자연적 근린공원으로, 도심 속에서 시민들에게 편안한 휴식과 조용한 산책을 제공한다. 산책로를 따라 빽빽이 들어선 나무들과 계절별로 피어나는 야생화가 선사하는 자연 풍경이 일품이다. 공원 정상 인근에서는 양천구 일대의 시원한 조망을 한눈에 담을 수 있으며, 주민들을 위한 운동 기구와 쉼터 벤치가 잘 조성되어 있어 가족 단위 산책객과 사진 작가들에게 아늑한 휴식처를 선사한다.' WHERE id = 2;
UPDATE spot SET overview = '강남 중심가에 위치한 강남 메디컬투어센터는 첨단 의료 서비스와 관광이 결합된 대한민국 웰니스 및 도심 관광의 핵심 거점이다. 강남구 일대의 명품 쇼핑거리, 트렌디한 카페, 패션 브랜드 숍과 인접해 있어 트렌디한 도심 문화를 만끽할 수 있다. 국내외 방문객을 위한 안내 시설과 휴게 공간이 잘 마련되어 있어 도심 관광의 즐거움을 한층 더해준다.' WHERE id = 3;
UPDATE spot SET overview = '강남 마이스 관광특구는 코엑스(COEX), 무역센터, 럭셔리 호텔과 쇼핑몰이 집중되어 있는 대한민국 대표 글로벌 비즈니스 및 문화 관광 구역이다. 대형 전시회와 국제 회의, K-POP 문화 행사 등이 상시 개최되며, 야간 경관 조명과 대형 미디어 파사드가 화려한 야경을 자랑한다. 쇼핑, 문화 체험, 맛집 탐방, 야경 촬영 등 다채로운 도심 엔터테인먼트를 즐길 수 있는 최고의 관광 명소이다.' WHERE id = 4;
UPDATE spot SET overview = '강변스파랜드는 서울 광진구 구의동 강변역 인근에 있는 대형 휴양 및 찜질방 시설로, 피로를 풀고자 하는 시민들과 여행객들에게 인기 높은 도심 속 웰니스 힐링 공간이다. 황토방, 소금방, 불가마 등 다채로운 테마의 온열 체험실과 넓은 족욕탕, 쾌적한 휴게실 시설을 완비하고 있다. 여행 후 지친 몸을 달래고 가족, 연인과 함께 편안하게 여유를 즐기기에 안성맞춤인 장소이다.' WHERE id = 5;
UPDATE spot SET overview = '강서습지생태공원은 한강 하류 강서구 양천로 일대에 형성된 생태 보전 구역으로, 버드나무 숲과 수생식물, 물새들이 서식하는 자연 습지 생태계의 보물창고이다. 한강변을 따라 조성된 산책로와 탐방 데크길에서는 계절마다 우거지는 억새와 갈대숲의 풍경을 감상할 수 있다. 조류 관찰대와 생태 학습 프로그램이 마련되어 있어 어린이 자연 학습과 고요한 스냅 사진 촬영 장소로 각광받고 있다.' WHERE id = 6;
