UPDATE spot SET overview = '금강보행교은 세종특별자치시 세종동 751-1 인근의 수려한 자연 경관을 자랑하는 대표적인 명소이다. 시원하게 펼쳐진 탁 트인 조망과 맑은 공기가 인상적이며, 계절에 따라 변하는 조망 풍경이 장관을 이룬다. 야외 활동과 산책, 탁 트인 시원한 풍경을 사진으로 담기에 매력적인 장소이다.' WHERE id = 133;
